UPDATE `quest_template` SET `entry`=488, `Method`=2, `ZoneOrSort`=141, `MinLevel`=4, `MaxLevel`=255, `QuestLevel`=5, `Type`=0, `RequiredClasses`=0, `RequiredRaces`=77, `RequiredSkill`=0, `RequiredSkillValue`=0, `RequiredCondition`=0, `RepObjectiveFaction`=0, `RepObjectiveValue`=0, `RequiredMinRepFaction`=0, `RequiredMinRepValue`=0, `RequiredMaxRepFaction`=0, `RequiredMaxRepValue`=0, `SuggestedPlayers`=0, `LimitTime`=0, `QuestFlags`=8, `SpecialFlags`=0, `PrevQuestId`=0, `NextQuestId`=0, `ExclusiveGroup`=0, `BreadcrumbForQuestId`=0, `NextQuestInChain`=0, `SrcItemId`=0, `SrcItemCount`=0, `SrcSpell`=0, `Title`='Zenn\'s Bidding', `Details`='Eager for work, I see.  Lucky for you a day never goes by that I don\'t wish I had a fledgling $c to perform my bidding.$B$BYou see, $N, I can make you very happy and provide you with things you never dreamed of having.  But in order for that to happen you must bring me certain items.$B$BMy business in the forest often requires certain. . .reagents.  Fetch for me 3 Nightsaber Fangs, 3 Strigid Owl Feathers and 3 swatches of Webwood Spider Silk.$B$BLet\'s keep this our little secret, $r.', `Objectives`='Bring Zenn Foulhoof outside of Dolanaar 3 Nightsaber Fangs, 3 Strigid Owl Feathers and 3 swatches of Webwood Spider Silk.', `OfferRewardText`='Ha ha! Well, done indeed.$B$BWho would have ever guessed that I, Zenn Foulhoof, would have a $R to do my bidding? Certainly not me! But so it goes... this beloved world of ours is full of surprises.$B$BThree cheers for the naive and gullible!', `RequestItemsText`='Have you been a busy little bee, $N? I\'ve been waiting for you to bring me what I need.', `EndText`='', `ObjectiveText1`='', `ObjectiveText2`='', `ObjectiveText3`='', `ObjectiveText4`='', `ReqItemId1`=3409, `ReqItemId2`=3411, `ReqItemId3`=3412, `ReqItemId4`=0, `ReqItemCount1`=3, `ReqItemCount2`=3, `ReqItemCount3`=3, `ReqItemCount4`=0, `ReqSourceId1`=0, `ReqSourceId2`=0, `ReqSourceId3`=0, `ReqSourceId4`=0, `ReqSourceCount1`=0, `ReqSource